//! A-05 Residuals Incongruence — outcome contract tests.
//!
//! Forces: S-08, S-09, S-10, S-11, S-14, S-15, S-16, S-18, S-20, S-21

use std::process::Command;
use tempfile::TempDir;

fn bin() -> std::path::PathBuf {
    env!("CARGO_BIN_EXE_residual").into()
}

fn run(dir: &TempDir, args: &[&str]) -> std::process::Output {
    Command::new(bin())
        .args(args)
        .current_dir(dir.path())
        .output()
        .expect("failed to run residual binary")
}

fn init(dir: &TempDir) {
    let out = run(dir, &["init"]);
    assert!(out.status.success(), "init failed: {}", String::from_utf8_lossy(&out.stderr));
}

// S-08: skill sessions detect absent metadata before producing architecture analysis

#[test]
fn skill_data_warns_when_metadata_absent() {
    let dir = TempDir::new().unwrap();
    init(&dir);
    let out = run(&dir, &["skill-data", "integrate"]);
    assert!(out.status.success());
    let stdout = String::from_utf8_lossy(&out.stdout).to_lowercase();
    assert!(
        stdout.contains("bootstrapping") || stdout.contains("absent metadata"),
        "skill-data must warn and offer bootstrapping when metadata is empty, got:\n{stdout}"
    );
}

// S-09: skill sessions surface unverified baseline before analysis

#[test]
fn skill_data_warns_when_verify_stamp_missing() {
    let dir = TempDir::new().unwrap();
    init(&dir);
    run(
        &dir,
        &[
            "add",
            "attractor",
            "--name",
            "X",
            "--description",
            "d",
            "--positive-state",
            "ok",
            "--negative-state",
            "bad",
        ],
    );
    let out = run(&dir, &["skill-data", "stressor-walk"]);
    assert!(out.status.success());
    let stdout = String::from_utf8_lossy(&out.stdout).to_lowercase();
    assert!(
        stdout.contains("unverified") || stdout.contains("verify all"),
        "skill-data should surface unverified baseline when no verify stamp exists, got:\n{stdout}"
    );
}

// S-10: tag-scan reports confidence; coverage-exempt stressors are suggestions not compliance

#[test]
fn tag_scan_reports_confidence_not_compliance() {
    let dir = TempDir::new().unwrap();
    init(&dir);
    run(
        &dir,
        &[
            "add",
            "stressor",
            "--description",
            "third party lib resists tags",
            "--attractor-id",
            "A-01",
            "--naive-change",
            "manual csv",
            "--coverage-exempt",
        ],
    );
    let out = run(&dir, &["tag", "scan", "."]);
    assert!(out.status.success());
    let stdout = String::from_utf8_lossy(&out.stdout).to_lowercase();
    assert!(
        stdout.contains("confidence") || stdout.contains("suggestion"),
        "tag scan should report confidence/suggestion not compliance, got:\n{stdout}"
    );
}

// S-11 / S-15: cross-store links — components and residues resolve in registry

#[test]
fn verify_links_catches_orphan_residue_component() {
    let dir = TempDir::new().unwrap();
    init(&dir);
    std::fs::write(
        dir.path().join("residual/residues.csv"),
        "id,force_id,component_id,status,notes\nR-01,S-01,orphan-component,proposed,note\n",
    )
    .unwrap();
    std::fs::write(
        dir.path().join("residual/forces.csv"),
        "id,kind,shortname,naive_change,outcomes,description,attractor_id,detection_mechanism\n\
         S-01,stressor,orphan-test,none,operator records residue,desc,A-01,verify exits non-zero\n",
    )
    .unwrap();
    std::fs::write(
        dir.path().join("residual/attractors.csv"),
        "id,name,description,positive_state,negative_state\n\
         A-01,Test,d,ok,bad\n",
    )
    .unwrap();
    std::fs::write(
        dir.path().join("residual/components.csv"),
        "name,description,status,architecture_set\ncli,hub,proposed,baseline\n",
    )
    .unwrap();
    let out = run(&dir, &["verify", "links"]);
    assert!(!out.status.success(), "verify links should fail on orphan component");
    let stdout = String::from_utf8_lossy(&out.stdout);
    assert!(
        stdout.contains("orphan-component") || stdout.contains("component"),
        "expected component link violation, got:\n{stdout}"
    );
}

#[test]
fn verify_links_catches_force_attractor_not_in_attractors_csv() {
    let dir = TempDir::new().unwrap();
    init(&dir);
    std::fs::write(
        dir.path().join("residual/forces.csv"),
        "id,kind,shortname,naive_change,outcomes,description,attractor_id,detection_mechanism\n\
         S-01,stressor,cross-store,none,operator records residue,desc,A-99,detect\n",
    )
    .unwrap();
    let out = run(&dir, &["verify", "links"]);
    assert!(!out.status.success());
    let stdout = String::from_utf8_lossy(&out.stdout);
    assert!(stdout.contains("A-99"), "expected missing attractor A-99, got:\n{stdout}");
}

// S-14: stressor forces declare detection mechanisms

#[test]
fn verify_links_catches_missing_detection_mechanism_on_stressor_force() {
    let dir = TempDir::new().unwrap();
    init(&dir);
    std::fs::write(
        dir.path().join("residual/attractors.csv"),
        "id,name,description,positive_state,negative_state\n\
         A-05,Incongruence,d,ok,bad\n",
    )
    .unwrap();
    std::fs::write(
        dir.path().join("residual/forces.csv"),
        "id,kind,shortname,naive_change,outcomes,description,attractor_id,detection_mechanism\n\
         S-14,stressor,fire-blind,add field,operator detects drift,desc,A-05,\n",
    )
    .unwrap();
    let out = run(&dir, &["verify", "links"]);
    assert!(!out.status.success());
    let stdout = String::from_utf8_lossy(&out.stdout);
    assert!(
        stdout.contains("detection") || stdout.contains("S-14"),
        "expected detection_mechanism violation, got:\n{stdout}"
    );
}

// S-16 / S-18: matrix filters by architecture_set

#[test]
fn matrix_show_architecture_set_filters_component_columns() {
    let dir = TempDir::new().unwrap();
    init(&dir);
    run(
        &dir,
        &[
            "add",
            "attractor",
            "--name",
            "X",
            "--description",
            "d",
            "--positive-state",
            "ok",
            "--negative-state",
            "bad",
        ],
    );
    run(
        &dir,
        &[
            "add",
            "stressor",
            "--description",
            "hits both sets",
            "--attractor-id",
            "A-01",
            "--naive-change",
            "none",
            "--components",
            "cli,alt-cli",
        ],
    );
    std::fs::write(
        dir.path().join("residual/components.csv"),
        "name,description,status,architecture_set\n\
         cli,baseline hub,proposed,baseline\n\
         alt-cli,proposed hub,proposed,alt-set\n",
    )
    .unwrap();
    std::fs::write(
        dir.path().join("residual/forces.csv"),
        "id,kind,shortname,naive_change,outcomes,description,attractor_id,detection_mechanism\n\
         S-01,stressor,dual-set,none,operator records residue,desc,A-01,detect\n",
    )
    .unwrap();
    let out = run(
        &dir,
        &["matrix", "show", "--csv", "--architecture-set", "alt-set"],
    );
    assert!(out.status.success(), "stderr={}", String::from_utf8_lossy(&out.stderr));
    let stdout = String::from_utf8_lossy(&out.stdout);
    assert!(stdout.contains("alt-cli"), "expected alt-set column, got:\n{stdout}");
    assert!(
        !stdout.contains(",cli,") && !stdout.starts_with("cli,"),
        "baseline-only column cli should be filtered out, got:\n{stdout}"
    );
}

// S-20: residue files preserve manual modifications — require --force on drift

#[test]
fn add_residue_requires_force_when_residues_manually_edited() {
    let dir = TempDir::new().unwrap();
    init(&dir);
    run(
        &dir,
        &[
            "add",
            "attractor",
            "--name",
            "X",
            "--description",
            "d",
            "--positive-state",
            "ok",
            "--negative-state",
            "bad",
        ],
    );
    run(
        &dir,
        &[
            "add",
            "stressor",
            "--description",
            "test",
            "--attractor-id",
            "A-01",
            "--naive-change",
            "none",
        ],
    );
    // Establish snapshot via a successful mutating command.
    run(
        &dir,
        &[
            "add",
            "term",
            "--term",
            "operator",
            "--definition",
            "human",
        ],
    );
    let path = dir.path().join("residual/residues.csv");
    let mut csv = std::fs::read_to_string(&path).unwrap_or_else(|_| {
        "id,force_id,component_id,status,notes\n".to_string()
    });
    csv.push_str("R-99,S-01,cli,proposed,manual annotation\n");
    std::fs::write(&path, csv).unwrap();

    let out = run(
        &dir,
        &[
            "add",
            "residue",
            "--force-id",
            "S-01",
            "--component-id",
            "cli",
            "--notes",
            "tool write",
        ],
    );
    assert!(
        !out.status.success(),
        "add residue should fail without --force after manual edit; stderr={}",
        String::from_utf8_lossy(&out.stderr)
    );
    let stderr = String::from_utf8_lossy(&out.stderr).to_lowercase();
    assert!(
        stderr.contains("--force") || stderr.contains("drift"),
        "expected drift/--force error, got:\n{stderr}"
    );
}

// S-21: skill sessions communicate fluent stressor entry

#[test]
fn skill_data_includes_fluent_usage_note() {
    let dir = TempDir::new().unwrap();
    init(&dir);
    let out = run(&dir, &["skill-data", "purpose-walk"]);
    assert!(out.status.success());
    let stdout = String::from_utf8_lossy(&out.stdout).to_lowercase();
    assert!(
        stdout.contains("fluent")
            || stdout.contains("any order")
            || stdout.contains("analytical lens"),
        "skill-data should counter phase-rigidity assumptions, got:\n{stdout}"
    );
}

