pub fn check_links(cfg: &Config) -> Result<Vec<LinkViolation>> {
    use crate::structure::analysis::force::ForceKind;
    use crate::structure::analysis::residues::{is_whole_system_residue, WHOLE_SYSTEM_COMPONENT};

    let stressors = crate::storage::stressors::load(&cfg.residual_dir)?;
    let purposes = crate::storage::purposes::load(&cfg.residual_dir)?;
    let attractors = crate::storage::attractors::load(&cfg.residual_dir)?;
    let forces = crate::storage::format::read_forces(&cfg.residual_dir)?;
    let residues = crate::storage::format::read_residues(&cfg.residual_dir)?;
    let components = crate::structure::definition::components::load(&cfg.residual_dir)?;

    let attractor_ids: std::collections::HashSet<String> =
        attractors.iter().map(|a| a.id.clone()).collect();
    let component_names: std::collections::HashSet<String> = components
        .iter()
        .map(|c| c.name.clone())
        .collect();

    let mut violations = Vec::new();

    for stressor in &stressors {
        if !stressor.attractor_id.is_empty() && !attractor_ids.contains(&stressor.attractor_id) {
            violations.push(LinkViolation {
                source: "stressor".to_string(),
                id: stressor.id.clone(),
                missing_attractor_id: stressor.attractor_id.clone(),
                reason: String::new(),
            });
        }
    }

    for purpose in &purposes {
        if !purpose.attractor_id.is_empty() && !attractor_ids.contains(&purpose.attractor_id) {
            violations.push(LinkViolation {
                source: "purpose".to_string(),
                id: purpose.id.clone(),
                missing_attractor_id: purpose.attractor_id.clone(),
                reason: String::new(),
            });
        }
    }

    for force in &forces {
        if !force.attractor_id.is_empty() && !attractor_ids.contains(&force.attractor_id) {
            violations.push(LinkViolation {
                source: "force".to_string(),
                id: force.id.clone(),
                missing_attractor_id: force.attractor_id.clone(),
                reason: String::new(),
            });
        }
        if force.kind == ForceKind::Stressor && force.detection_mechanism.trim().is_empty() {
            violations.push(LinkViolation {
                source: "force".to_string(),
                id: force.id.clone(),
                missing_attractor_id: String::new(),
                reason: "missing detection_mechanism (observable signal for attractor drift)".to_string(),
            });
        }
    }

    for residue in &residues {
        if is_whole_system_residue(residue) || residue.component_id == WHOLE_SYSTEM_COMPONENT {
            continue;
        }
        if !component_names.contains(&residue.component_id) {
            violations.push(LinkViolation {
                source: "residue".to_string(),
                id: residue.id.clone(),
                missing_attractor_id: String::new(),
                reason: format!(
                    "component_id '{}' not found in components.csv",
                    residue.component_id
                ),
            });
        }
    }

    Ok(violations)
}

