fn append_session_guards(
    out: &mut String,
    skill_name: &str,
    attractors: &[crate::storage::attractors::Attractor],
    stressors: &[crate::storage::stressors::Stressor],
    purposes: &[crate::storage::purposes::Purpose],
    residual_dir: &std::path::Path,
) {
    out.push_str("## Fluent Usage\n");
    out.push_str(
        "Residual is **fluent**: record stressors, purposes, terms, and attractors in any order, \
         at any phase, without switching skills. Skills are analytical lenses — invoke only what \
         your workflow needs.\n\n",
    );

    let needs_attractors = matches!(skill_name, "stressor-walk" | "integrate" | "fmea" | "atam" | "purpose-walk");
    let needs_stressors = matches!(skill_name, "stressor-walk" | "integrate" | "fmea" | "atam");
    let metadata_absent = (needs_attractors && attractors.is_empty())
        || (needs_stressors && stressors.is_empty())
        || (skill_name == "purpose-walk" && purposes.is_empty());

    if metadata_absent {
        out.push_str("## Session Guard — Absent Metadata\n");
        out.push_str(
            "WARNING: required metadata is missing or empty. Prefer capture-first mode before analysis.\n\n",
        );
        out.push_str("Bootstrapping checklist:\n");
        out.push_str("- [ ] `residual init` (if residual/ missing)\n");
        out.push_str("- [ ] `residual add attractor` — define positive and negative state pressure\n");
        out.push_str("- [ ] `residual add term` — seed terminology for outcome validation\n");
        if needs_stressors {
            out.push_str("- [ ] `residual add stressor` — record at least one stressor narrative\n");
        }
        if skill_name == "purpose-walk" || skill_name == "naive-draft" {
            out.push_str("- [ ] `residual add purpose` — record at least one purpose\n");
        }
        out.push_str("- [ ] `residual verify all` — establish a verified baseline\n\n");
    }

    if !crate::verification::verify_stamp_exists(residual_dir) {
        out.push_str("## Session Guard — Unverified Baseline\n");
        out.push_str(
            "WARNING: no verified baseline stamp found. Recent residual/ edits may not have passed \
             `residual verify all`. Treat analysis as change-tracking until verify passes.\n\n",
        );
    } else if skill_name == "stressor-walk" || skill_name == "integrate" {
        out.push_str("## Baseline\n");
        out.push_str("Verified baseline stamp present. Skill sessions may proceed to analysis.\n\n");
    }

    let persona_names = crate::storage::personas::list_names(residual_dir).unwrap_or_default();
    if matches!(skill_name, "stressor-walk" | "fmea" | "atam") && persona_names.len() < 2 {
        out.push_str("## Persona Adequacy\n");
        out.push_str(
            "NOTE: walks benefit from at least two personas (stakeholder + direct user) until \
             alpha/beta exist. Add personas with `residual add persona` when ready.\n\n",
        );
    }
}

