/// Restrict columns to components registered under `architecture_set` (S-16/S-18).
pub fn filter_architecture_set(
    self,
    set: &str,
    residual_dir: &std::path::Path,
) -> Result<Self> {
    let registry = crate::structure::definition::components::load(residual_dir)?;
    let allowed: HashSet<String> = registry
        .iter()
        .filter(|c| c.architecture_set == set)
        .map(|c| c.name.clone())
        .collect();
    let keep: Vec<usize> = self
        .components
        .iter()
        .enumerate()
        .filter(|(_, name)| allowed.contains(*name))
        .map(|(i, _)| i)
        .collect();
    let components: Vec<String> = keep.iter().map(|&i| self.components[i].clone()).collect();
    let cells: Vec<Vec<u8>> = self
        .cells
        .iter()
        .map(|row| keep.iter().map(|&i| row[i]).collect())
        .collect();
    Ok(NkpMatrix {
        stressor_ids: self.stressor_ids,
        attractor_ids: self.attractor_ids,
        components,
        cells,
    })
}

