const VERIFY_STAMP: &str = ".verify-stamp";

pub fn write_verify_stamp(residual_dir: &Path) -> Result<()> {
    let stamp = format!(
        "verified_at={}\n",
        chrono::Local::now().format("%Y-%m-%dT%H:%M:%S")
    );
    std::fs::write(residual_dir.join(VERIFY_STAMP), stamp)?;
    Ok(())
}

pub fn verify_stamp_exists(residual_dir: &Path) -> bool {
    residual_dir.join(VERIFY_STAMP).exists()
}

