pub fn check_links(cfg: &Config) -> Result<Vec<LinkViolation>> {
    use crate::structure::analysis::force::ForceKind;
    use crate::structure::analysis::residues::{Residue, WHOLE_SYSTEM_COMPONENT};
    use std::collections::HashSet;

    let dir = &cfg.residual_dir;
    let stressors = crate::storage::stressors::load(dir)?;
    let purposes = crate::storage::purposes::load(dir)?;
    let attractors = crate::storage::attractors::load(dir)?;
    let forces = crate::storage::format::read_forces(dir)?;
    let residues: Vec<Residue> = crate::storage::format::read_residues(dir)?;
    let components = crate::structure::definition::components::load(dir)?;

    let attractor_ids: HashSet<String> = attractors.iter().map(|a| a.id.clone()).collect();
    let component_names: HashSet<String> = components.iter().map(|c| c.name.clone()).collect();
    let force_ids: HashSet<String> = forces.iter().map(|f| f.id.clone()).collect();

    let mut violations = Vec::new();

    for stressor in &stressors {
        if !stressor.attractor_id.is_empty() && !attractor_ids.contains(&stressor.attractor_id) {
            violations.push(LinkViolation {
                source: "stressor".to_string(),
                id: stressor.id.clone(),
                detail: format!("missing attractor '{}'", stressor.attractor_id),
            });
        }
    }

    for purpose in &purposes {
        if !purpose.attractor_id.is_empty() && !attractor_ids.contains(&purpose.attractor_id) {
            violations.push(LinkViolation {
                source: "purpose".to_string(),
