        );
    }
    Ok(())
}

const VERIFY_STAMP: &str = ".verify-stamp";

pub fn verify_stamp_path(residual_dir: &Path) -> std::path::PathBuf {
    residual_dir.join(VERIFY_STAMP)
}

pub fn verify_stamp_exists(residual_dir: &Path) -> bool {
    verify_stamp_path(residual_dir).is_file()
}

pub fn write_verify_stamp(residual_dir: &Path) -> Result<()> {
    let now = chrono::Local::now().format("%Y-%m-%dT%H:%M:%S").to_string();
    std::fs::write(
        verify_stamp_path(residual_dir),
        format!("verified_at={now}\n"),
    )?;
    Ok(())
}

