use anyhow::{bail, Result};
use std::path::Path;

use crate::storage::format::{read_residues, write_residues};
use crate::structure::analysis::residues::Residue;

pub fn load(residual_dir: &Path) -> Result<Vec<Residue>> {
    read_residues(residual_dir)
}

pub fn append(residual_dir: &Path, residue: Residue) -> Result<()> {
    let mut all = load(residual_dir)?;
    all.push(residue);
    write_residues(residual_dir, &all)
}

pub fn next_id(residues: &[Residue]) -> String {
    let max = residues
        .iter()
        .filter_map(|r| r.id.strip_prefix("R-").and_then(|n| n.parse::<u32>().ok()))
        .max()
        .unwrap_or(0);
    format!("R-{:02}", max + 1)
}

pub fn force_exists(residual_dir: &Path, force_id: &str) -> Result<bool> {
    if crate::storage::stressors::load(residual_dir)?
        .iter()
        .any(|s| s.id == force_id)
    {
        return Ok(true);
    }
    if crate::storage::purposes::load(residual_dir)?
        .iter()
        .any(|p| p.id == force_id)
    {
        return Ok(true);
    }
    Ok(crate::storage::format::read_forces(residual_dir)?
        .iter()
        .any(|f| f.id == force_id))
}

pub fn append_whole_system(residual_dir: &Path, force_id: &str, notes: &str) -> Result<String> {
    if !force_exists(residual_dir, force_id)? {
        bail!("force id '{}' not found in stressors, purposes, or forces", force_id);
    }
    let id = next_id(&load(residual_dir)?);
    append(
        residual_dir,
        Residue::whole_system(id.clone(), force_id, notes),
    )?;
    Ok(id)
}

//! +/- Residues schema — force ↔ component mapping.

pub const WHOLE_SYSTEM_STATUS: &str = "whole-system-residue";
pub const WHOLE_SYSTEM_COMPONENT: &str = "whole-system";

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Residue {
    pub id: String,
    pub force_id: String,
    pub component_id: String,
    pub status: String,
    pub notes: String,
}

impl Residue {
    pub fn new(
        id: impl Into<String>,
        force_id: impl Into<String>,
        component_id: impl Into<String>,
    ) -> Self {
        Self {
            id: id.into(),
            force_id: force_id.into(),
            component_id: component_id.into(),
            status: "proposed".into(),
            notes: String::new(),
        }
    }

    pub fn whole_system(
        id: impl Into<String>,
        force_id: impl Into<String>,
        notes: impl Into<String>,
    ) -> Self {
        Self {
            id: id.into(),
            force_id: force_id.into(),
            component_id: WHOLE_SYSTEM_COMPONENT.into(),
            status: WHOLE_SYSTEM_STATUS.into(),
            notes: notes.into(),
        }
    }

    pub fn is_whole_system(&self) -> bool {
        self.status == WHOLE_SYSTEM_STATUS || self.component_id == WHOLE_SYSTEM_COMPONENT
    }
}

