    let residues = crate::storage::format::read_residues(dir)?;
    let components = crate::structure::definition::components::load(dir)?;

    let attractor_ids: std::collections::HashSet<String> =
        attractors.iter().map(|a| a.id.clone()).collect();
    let component_names: std::collections::HashSet<String> =
        components.iter().map(|c| c.name.clone()).collect();
    let force_ids: std::collections::HashSet<String> =
        forces.iter().map(|f| f.id.clone()).collect();

    let mut violations = Vec::new();

    for stressor in &stressors {
        if !stressor.attractor_id.is_empty() && !attractor_ids.contains(&stressor.attractor_id) {
            violations.push(LinkViolation {
                source: "stressor".to_string(),
                id: stressor.id.clone(),
                message: format!("missing attractor '{}'", stressor.attractor_id),
            });
        }
    }

    for purpose in &purposes {
        if !purpose.attractor_id.is_empty() && !attractor_ids.contains(&purpose.attractor_id) {
            violations.push(LinkViolation {
                source: "purpose".to_string(),
                id: purpose.id.clone(),
                message: format!("missing attractor '{}'", purpose.attractor_id),
            });
        }
    }

    for force in &forces {
        if !force.attractor_id.is_empty() && !attractor_ids.contains(&force.attractor_id) {
            violations.push(LinkViolation {
                source: "force".to_string(),
                id: force.id.clone(),
                message: format!("missing attractor '{}'", force.attractor_id),
            });
        }
        if force.kind == ForceKind::Stressor && force.detection_mechanism.trim().is_empty() {
            violations.push(LinkViolation {
                source: "force".to_string(),
                id: force.id.clone(),
                message: "missing detection_mechanism for stressor force".to_string(),
            });
        }
    }

    for residue in &residues {
        if !residue.force_id.is_empty()
            && !force_ids.contains(&residue.force_id)
            && !stressors.iter().any(|s| s.id == residue.force_id)
            && !purposes.iter().any(|p| p.id == residue.force_id)
        {
            violations.push(LinkViolation {
                source: "residue".to_string(),
                id: residue.id.clone(),
                message: format!("unknown force_id '{}'", residue.force_id),
            });
        }
        let comp = residue.component_id.trim();
        if !comp.is_empty()
            && comp != WHOLE_SYSTEM_COMPONENT
            && !component_names.contains(comp)
        {
            violations.push(LinkViolation {
                source: "residue".to_string(),
                id: residue.id.clone(),
                message: format!("component '{}' not in components.csv registry", comp),
            });
        }
    }

    Ok(violations)
}

