    /// Keep only component columns registered under the given architecture_set.
    pub fn filter_architecture_set(
        &mut self,
        residual_dir: &std::path::Path,
        set: &str,
    ) -> Result<()> {
        use crate::structure::definition::components;
        let registry = components::load(residual_dir)?;
        let allowed: HashSet<String> = registry
            .iter()
            .filter(|c| c.architecture_set == set)
            .map(|c| c.name.clone())
            .collect();
        if allowed.is_empty() {
            self.components.clear();
            self.cells = self.cells.iter().map(|_| vec![]).collect();
            return Ok(());
        }
        let keep: Vec<usize> = self
            .components
            .iter()
            .enumerate()
            .filter(|(_, name)| allowed.contains(*name))
            .map(|(i, _)| i)
            .collect();
        self.components = keep.iter().map(|&i| self.components[i].clone()).collect();
        self.cells = self
            .cells
            .iter()
            .map(|row| keep.iter().map(|&i| row[i]).collect())
            .collect();
        Ok(())
    }
}

