fn write_all(residual_dir: &Path, rows: &[Stressor]) -> Result<()> {
    let mut buf = String::from(
        "id,description,naive_change,outcomes,components_affected,attractor_id,coverage_exempt\n",
    );
    for s in rows {
        let mut row = Vec::new();
        {
            let mut wtr = csv::WriterBuilder::new().has_headers(false).from_writer(&mut row);
            wtr.write_record(&[
                &s.id,
                &s.description,
                &s.naive_change,
                &s.outcomes,
                &s.components_affected,
                &s.attractor_id,
                if s.coverage_exempt { "true" } else { "false" },
            ])?;
            wtr.flush()?;
        }
        buf.push_str(std::str::from_utf8(&row)?);
    }
    std::fs::write(residual_dir.join("stressors.csv"), buf)?;
    Ok(())
}

