/// Keep only component columns whose names appear in `allowed`.
pub fn filter_columns(&mut self, allowed: &HashSet<String>) {
    if allowed.is_empty() {
        return;
    }
    let mut keep_indices = Vec::new();
    let mut new_components = Vec::new();
    for (idx, comp) in self.components.iter().enumerate() {
        if allowed.contains(comp) {
            keep_indices.push(idx);
            new_components.push(comp.clone());
        }
    }
    self.components = new_components;
    for row in &mut self.cells {
        *row = keep_indices.iter().map(|&i| row[i]).collect();
    }
}

