pub fn verify_stamp_path(residual_dir: &Path) -> std::path::PathBuf {
    residual_dir.join(".verify-stamp")
}

pub fn verify_stamp_exists(residual_dir: &Path) -> bool {
    verify_stamp_path(residual_dir).exists()
}

pub fn write_verify_stamp(residual_dir: &Path) -> Result<()> {
    let stamp = format!(
        "verified={}\\n",
        chrono::Local::now().format("%Y-%m-%dT%H:%M:%S")
    );
    std::fs::write(verify_stamp_path(residual_dir), stamp)?;
    Ok(())
}

